//! 📄️ PDF 1.4 page targets over its own resolved document model.
use crate::standards::v1_4::subsets::base::schema::{snapshot::PdfSnapshot, mutations::{PdfMutation, ReplacePageText}};
use semio_framework_plugin::{Fault, FaultCode, FaultOrigin, TreeWindows};
use semio_framework_plugin::app::{DocumentWindowKit, EditableDocumentPage, EditableDocumentView};
use semio_framework_ui_contract::{BuiltNode, UiPublicationRevision};
use semio_framework_ui_locale::Locale;

fn refusal(code: &'static str, message: &'static str) -> Fault {
    Fault::new(FaultOrigin::App, FaultCode::new(code), message)
}

pub fn editable_view(document: &PdfSnapshot, publication_revision: UiPublicationRevision) -> Result<EditableDocumentView, Fault> {
    let pages = document.pages.iter().enumerate().map(|(index, page)| {
        let index = u32::try_from(index).map_err(|_| refusal("stdio.pdf.1.4.page-index", "Page index exceeds the document action address"))?;
        Ok(EditableDocumentPage::new(index, 0, page.text.clone()))
    }).collect::<Result<Vec<_>, Fault>>()?;
    Ok(EditableDocumentView { pages, publication_revision })
}

pub fn render_windowed(view: &EditableDocumentView, windows: &TreeWindows<'_>, locale: Locale) -> semio_framework_plugin::UiAssemblyResult<BuiltNode> {
    DocumentWindowKit::render_editable_windowed(view, windows, locale)
}

pub fn text_edit_mutation(document: &PdfSnapshot, page: u32, item: u32, revision: &str, text: &str) -> Result<Option<PdfMutation>, Fault> {
    if item != 0 { return Err(refusal("stdio.pdf.1.4.text-item", "PageDoc owns exactly one text item")); }
    let index = usize::try_from(page).map_err(|_| refusal("stdio.pdf.1.4.page-index", "Page index exceeds this platform"))?;
    let original = document.pages.get(index).ok_or_else(|| refusal("stdio.pdf.1.4.page-index", "Page target does not exist"))?;
    if DocumentWindowKit::text_revision(&original.text) != revision {
        return Err(refusal("stdio.pdf.1.4.stale-text", "Page text revision no longer matches"));
    }
    if original.text == text { return Ok(None); }
    Ok(Some(PdfMutation::ReplacePageText(ReplacePageText { index, text: text.into() })))
}
